#include <string>

class Solution {
public:
    bool checkDivisibility(int n) {
        int temp = std::abs(n);
        int sum = 0;
        long long prod = 1;
        while (temp > 0) {
            int d = temp % 10;
            sum += d;
            prod *= d;
            temp /= 10;
        }
        if (sum == 0 || n % sum != 0) return false;
        if (prod > 0 && n % prod != 0) return false;
        return true;
    }
};

