var checkDivisibility = function(n) {
    let temp = Math.abs(n);
    let sum = 0;
    let prod = 1n;
    while (temp > 0) {
        const d = temp % 10;
        sum += d;
        prod *= BigInt(d);
        temp = Math.floor(temp / 10);
    }
    if (sum === 0 || n % sum !== 0) return false;
    if (prod > 0n && BigInt(n) % prod !== 0n) return false;
    return true;
};
